SELECT bi_dim_branch.branch_code AS k0, (CAST(CASE WHEN (count(CASE WHEN (bi_agg_position_daily.position_type IN (?) AND bi_agg_position_daily.dpd_band IS NOT NULL) THEN ? END) > ?) THEN sum(CASE WHEN (bi_agg_position_daily.position_type IN (?)) THEN CASE WHEN (bi_agg_position_daily.dpd_band IN (?, ?, ?)) THEN bi_agg_position_daily.classification_exposure_rc_sum ELSE ? END END) END AS FLOAT) / (nullif(sum(CASE WHEN (bi_agg_position_daily.position_type IN (?) AND bi_agg_position_daily.dpd_band IS NOT NULL) THEN bi_agg_position_daily.classification_exposure_rc_sum END), ?) + 0.0)) * ? AS m0, CASE WHEN (count(CASE WHEN (bi_agg_position_daily.position_type IN (?) AND bi_agg_position_daily.dpd_band IS NOT NULL) THEN ? END) > ?) THEN sum(CASE WHEN (bi_agg_position_daily.position_type IN (?)) THEN CASE WHEN (bi_agg_position_daily.dpd_band IN (?, ?, ?)) THEN bi_agg_position_daily.classification_exposure_rc_sum ELSE ? END END) END AS m1
FROM bi_agg_position_daily LEFT OUTER JOIN bi_dim_branch ON bi_dim_branch.organization_id = bi_agg_position_daily.organization_id AND bi_dim_branch.bank_id = bi_agg_position_daily.bank_id AND bi_dim_branch.branch_code = bi_agg_position_daily.branch_code
WHERE bi_agg_position_daily.organization_id = ? AND bi_agg_position_daily.bank_id = ? AND bi_agg_position_daily.as_of_date = ? GROUP BY bi_dim_branch.branch_code ORDER BY k0 ASC NULLS LAST
 LIMIT ? OFFSET ?
